agent_detail.agent_sql:
SELECT (AVG(?cost) AS ?avgCost)
WHERE {
  ?m a <http://bird-bird_student_club-ontology-20260805-010541/ontology/vkg-bird_student_club/Member> ;
     <http://bird-bird_student_club-ontology-20260805-010541/ontology/vkg-bird_student_club/Member/first_name> "Elijah" ;
     <http://bird-bird_student_club-ontology-20260805-010541/ontology/vkg-bird_student_club/Member/last_name> "Allen" .
  ?e a <http://bird-bird_student_club-ontology-20260805-010541/ontology/vkg-bird_student_club/Expense> ;
     <http://bird-bird_student_club-ontology-20260805-010541/ontology/vkg-bird_student_club/Expense/hasMember> ?m ;
     <http://bird-bird_student_club-ontology-20260805-010541/ontology/vkg-bird_student_club/Expense/expense_date> ?d ;
     <http://bird-bird_student_club-ontology-20260805-010541/ontology/vkg-bird_student_club/Expense/cost> ?cost .
  BIND(SUBSTR(STR(?d),6,2) AS ?month)
  FILTER(?month = "09" || ?month = "10")
}

SELECT (COUNT(*) AS ?count) WHERE {
  ?member a <http://bird-bird_student_club-ontology-20260804-134446/ontology/vkg-bird_student_club/Member> ;
    <http://bird-bird_student_club-ontology-20260804-134446/ontology/vkg-bird_student_club/Member/hasMajor> ?major ;
    <http://bird-bird_student_club-ontology-20260804-134446/ontology/vkg-bird_student_club/Member/t_shirt_size> ?size .
  ?major a <http://bird-bird_student_club-ontology-20260804-134446/ontology/vkg-bird_student_club/Major> ;
    <http://bird-bird_student_club-ontology-20260804-134446/ontology/vkg-bird_student_club/Major/major_name> "Business" .
  FILTER(?size = "Medium")
}

SELECT (COUNT(DISTINCT ?city) AS ?n) WHERE {
  ?z a <http://bird-bird_student_club-ontology-20260804-134446/ontology/vkg-bird_student_club/ZipCode> ;
     <http://bird-bird_student_club-ontology-20260804-134446/ontology/vkg-bird_student_club/ZipCode/county> ?county ;
     <http://bird-bird_student_club-ontology-20260804-134446/ontology/vkg-bird_student_club/ZipCode/state> ?state ;
     <http://bird-bird_student_club-ontology-20260804-134446/ontology/vkg-bird_student_club/ZipCode/city> ?city .
  FILTER(?county = "Orange County" && ?state = "Virginia")
}

SELECT ?first_name ?last_name WHERE {
  ?member a <http://bird-bird_student_club-ontology-20260804-134446/ontology/vkg-bird_student_club/Member> ;
          <http://bird-bird_student_club-ontology-20260804-134446/ontology/vkg-bird_student_club/Member/hasMajor> ?major ;
          <http://bird-bird_student_club-ontology-20260804-134446/ontology/vkg-bird_student_club/Member/first_name> ?first_name ;
          <http://bird-bird_student_club-ontology-20260804-134446/ontology/vkg-bird_student_club/Member/last_name> ?last_name .
  ?major a <http://bird-bird_student_club-ontology-20260804-134446/ontology/vkg-bird_student_club/Major> ;
         <http://bird-bird_student_club-ontology-20260804-134446/ontology/vkg-bird_student_club/Major/department> "School of Applied Sciences, Technology and Education" .
}

SELECT (COUNT(*) AS ?n) WHERE {
  {
    SELECT ?eid ?type (COUNT(?member) AS ?cnt) WHERE {
      ?event a <http://bird-bird_student_club-ontology-20260804-134446/ontology/vkg-bird_student_club/Event> ;
             <http://bird-bird_student_club-ontology-20260804-134446/ontology/vkg-bird_student_club/Event/event_id> ?eid ;
             <http://bird-bird_student_club-ontology-20260804-134446/ontology/vkg-bird_student_club/Event/type> ?type .
      ?att a <http://bird-bird_student_club-ontology-20260804-134446/ontology/vkg-bird_student_club/Attendance> ;
           <http://bird-bird_student_club-ontology-20260804-134446/ontology/vkg-bird_student_club/Attendance/link_to_event> ?eid ;
           <http://bird-bird_student_club-ontology-20260804-134446/ontology/vkg-bird_student_club/Attendance/link_to_member> ?member .
    }
    GROUP BY ?eid ?type
  }
  FILTER(xsd:decimal(?cnt) > 10 && LCASE(?type) = "meeting")
}

SELECT ?last_name ?department ?college WHERE {
  ?member a <http://bird-bird_student_club-ontology-20260804-134446/ontology/vkg-bird_student_club/Member> ;
          <http://bird-bird_student_club-ontology-20260804-134446/ontology/vkg-bird_student_club/Member/last_name> ?last_name ;
          <http://bird-bird_student_club-ontology-20260804-134446/ontology/vkg-bird_student_club/Member/hasMajor> ?major .
  ?major a <http://bird-bird_student_club-ontology-20260804-134446/ontology/vkg-bird_student_club/Major> ;
         <http://bird-bird_student_club-ontology-20260804-134446/ontology/vkg-bird_student_club/Major/major_name> ?major_name ;
         <http://bird-bird_student_club-ontology-20260804-134446/ontology/vkg-bird_student_club/Major/department> ?department ;
         <http://bird-bird_student_club-ontology-20260804-134446/ontology/vkg-bird_student_club/Major/college> ?college .
  FILTER(LCASE(?major_name) = "environmental engineering")
}

SELECT ?fullName ?cost WHERE {
  ?m a <http://bird-bird_student_club-ontology-20260804-134446/ontology/vkg-bird_student_club/Member> ;
     <http://bird-bird_student_club-ontology-20260804-134446/ontology/vkg-bird_student_club/Member/first_name> ?fn ;
     <http://bird-bird_student_club-ontology-20260804-134446/ontology/vkg-bird_student_club/Member/last_name> ?ln .
  BIND(CONCAT(?fn, " ", ?ln) AS ?fullName)
  FILTER(false)
}

SELECT DISTINCT ?category WHERE {
  ?event a <http://bird-bird_student_club-ontology-20260804-134446/ontology/vkg-bird_student_club/Event> ;
         <http://bird-bird_student_club-ontology-20260804-134446/ontology/vkg-bird_student_club/Event/location> "MU 215" ;
         <http://bird-bird_student_club-ontology-20260804-134446/ontology/vkg-bird_student_club/Event/type> "Guest Speaker" ;
         <http://bird-bird_student_club-ontology-20260804-134446/ontology/vkg-bird_student_club/Event/event_id> ?eventId .
  ?budget a <http://bird-bird_student_club-ontology-20260804-134446/ontology/vkg-bird_student_club/Budget> ;
          <http://bird-bird_student_club-ontology-20260804-134446/ontology/vkg-bird_student_club/Budget/link_to_event> ?eventId ;
          <http://bird-bird_student_club-ontology-20260804-134446/ontology/vkg-bird_student_club/Budget/spent> ?spent ;
          <http://bird-bird_student_club-ontology-20260804-134446/ontology/vkg-bird_student_club/Budget/category> ?category .
  FILTER(xsd:decimal(?spent) = 0)
}
